{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Dronedarone has an absolute oral bioavailability of only ~4% in humans under fasting conditions, attributed to extensive first-pass metabolism; despite a different scaffold, it shares the query's large lipophilic aromatic/amine character and demonstrates that such molecules can fall far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Tiracizine, a carbamate-containing lipophilic drug, has a mean systemic availability of 34% with a wide range (16-68%) due to substantial presystemic metabolism; this is above the threshold but highlights first-pass liability in a structurally related ester/carbamate context.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C49"],
      "claim": "Azilsartan, a prodrug-derived ARB, shows ~58% absolute bioavailability in humans, indicating that ester prodrugs can achieve high F when absorption is efficient and first-pass metabolism is low; this is a high-F counterexample.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a large lipophilic double prodrug (hexyl carbamate-protected amidine plus ethyl ester) with multiple heterocycles and a basic pyridine, features associated with extensive presystemic metabolism and efflux. The most mechanistically transferable experimental evidence is dronedarone's ~4% absolute bioavailability due to first-pass metabolism, supporting F < 20%. Several moderate-to-high F analogues exist, but they are structurally distant and lack the same double-prodrug/large lipophilic liability; their transferability is low. Overall, low oral bioavailability is better supported, with low confidence due to the low Morgan similarities.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule in the provided evidence set.",
    "All retrieved analogues have low Morgan similarity (~0.19-0.21), limiting structural transferability.",
    "No P-glycoprotein/efflux or first-pass hydrolysis data specific to the query's carbamate/ester prodrug moieties."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "low",
      "card_ids": ["C29"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "dronedarone"
    },
    {
      "applicability": "low",
      "card_ids": ["C52"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "tiracizine"
    },
    {
      "applicability": "low",
      "card_ids": ["C49"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "azilsartan"
    }
  ],
  "revision_action": "initial"
}

